Deno.test({
  name: "knowledge-bases model: HTTP errors name the request and status",
  sanitizeResources: false,
  fn: async () => {
    await withMockApi({
      "GET /api/knowledge-base-jobs/test-id-123": {
        status: 500,
        json: { message: "boom" },
      },
    }, async ({ run }) => {
      const err = await assertRejects(
        () =>
          run("get_knowledge_base_job", {
            "knowledge_base_job_id": "test-id-123",
          }),
        Error,
      );
      assertStringIncludes(
        err.message,
        "GET /api/knowledge-base-jobs/test-id-123",
      );
      assertStringIncludes(err.message, "500");
      assertStringIncludes(err.message, "boom");
    });
  },
});

